        "**Його вже спалювали.** 24 серпня 1814 року британські війська увійшли у Вашингтон і підпалили Білий дім разом з Капітолієм — помста за спалене американцями місто в Канаді. Долі Медісон, дружина президента, встигла вивезти портрет Джорджа Вашингтона роботи Гілберта Стюарта, наказавши виламати раму. Від будівлі лишилися обгорілі стіни, врятував їх раптовий зливовий шторм, що загасив вогонь.\n\nА тепер поєднай дати: **за три тижні після цього**, у вересні 1814-го, британці пішли на Балтимор, усю ніч обстрілювали форт Мак-Генрі — і той прапор, що вистояв до ранку, ти побачиш у Музеї американської історії за два квартали звідси. Одна війна, одні й ті самі три тижні, два експонати в різних кінцях Моллу.\n\nІ ще дрібниця для Лафаєт-сквер: церква Святого Іоанна навпроти називається «церквою президентів» — кожен президент від Медісона бував тут принаймні раз, а 54-та лава офіційно президентська.",
