        "Ці дві іржаві конструкції — **трансферні мости Лонг-Айлендської залізниці**. До 1967 року ними закочували вантажні вагони просто на баржі й перевозили через Іст-Рівер: тунелів для вантажу не було, і весь товар їздив до Мангеттена водою.\n\nІ ось що цікаво особисто для тебе: **ти побачиш три уламки однієї й тієї ж зниклої системи за три дні.** 16-го пройдеш **Хай-Лайн** — вантажну естакаду, закриту в 1980-му. 18-го станеш тут, біля ґантрі, якими вагони з'їжджали на баржі. А 20-го на пробіжці Гудзоном пробіжиш повз **точно такий самий ґантрі** в Riverside Park South, на тому березі. Одна мережа, три її кістки.\n\nВивіска Pepsi світиться над цим берегом **з 1936 року** — лишилася від заводу, який давно знесли. У 2016-му її офіційно визнали памʼяткою Нью-Йорка: тридцять сім метрів завдовжки, і вночі червоне відображення лягає на воду.",
