        "Статую подарувала Франція, обличчя Бартольді ліпив, за переказом, зі своєї матері, а залізний кістяк усередині спроєктував Гюстав Ейфель — за кілька років до своєї вежі. Мідна шкіра завтовшки всього 2,4 мм, тобто як дві монети: вся конструкція тримається не на товщині металу, а на інженерії.\n\nУ короні 25 вікон і сім променів у діадемі. Перші шістнадцять років статуя офіційно числилася маяком, тільки світила так погано, що з цієї затії відмовились. Факел, який ти бачиш зараз, — копія 1986 року, а оригінал 1886-го стоїть унизу в музеї на острові, і його можна обійти впритул.\n\nІ одна деталь, заради якої варто подивитися вниз: біля ніг статуї лежать **розірвані кайдани**. З землі їх майже не видно — і це не випадковість. Бартольді спершу хотів дати їй у руку розірваний ланцюг як знак скасування рабства, але замовники вирішили, що для США 1870-х це надто гостро, і кайдани переїхали під поділ сукні, де їх майже не помітно.",
